import { useState, useMemo, useEffect } from 'react';

export const useColumnVisibility = (initialColumns = []) => {
    const [dispColumns, setDispColumns] = useState(initialColumns);

    useEffect(() => {
        setDispColumns(prev => {
            return initialColumns.map(newCol => {
                const existing = prev.find(p => p.Field_Name === newCol.Field_Name);
                if (existing) {
                    return {
                        ...newCol,
                        isVisible: existing.isVisible,
                        OrderBy: existing.OrderBy,
                        Aggregation: existing.Aggregation
                    };
                }
                return newCol;
            });
        });
    }, [initialColumns]);

    const toggleColumn = (fieldName, visible) => {
        setDispColumns(cols =>
            cols.map(col =>
                col.Field_Name === fieldName
                    ? { ...col, isVisible: visible ? 1 : 0 }
                    : col
            )
        );
    };

    const reorderColumn = (fieldName, order) => {
        setDispColumns(cols =>
            cols.map(col =>
                col.Field_Name === fieldName
                    ? { ...col, OrderBy: Number(order) }
                    : col
            )
        );
    };

    const updateAggregation = (fieldName, aggType) => {
        setDispColumns(cols =>
            cols.map(col =>
                col.Field_Name === fieldName
                    ? { ...col, Aggregation: aggType }
                    : col
            )
        );
    };

    const orderedColumns = useMemo(() => [...dispColumns].sort(
        (a, b) => (a.OrderBy ?? 999) - (b.OrderBy ?? 999)
    ), [dispColumns]);

    return {
        dispColumns: orderedColumns,
        rawColumns: dispColumns,
        setDispColumns,
        toggleVisibility: toggleColumn,
        updateOrder: reorderColumn,
        updateAggregation
    };
};

